import {calculateCostModel, validCostModel, projectPeriod, newCostModel, modelExchangeRate} from './planning.js?v=3';

const $ = id => document.getElementById(id);
const money = n => new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(n);
const decimal = n => new Intl.NumberFormat('fr-FR',{maximumFractionDigits:4}).format(n);
const dateLabel = iso => new Intl.DateTimeFormat('fr-FR',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(iso));
const uid = () => crypto.randomUUID();
const CATEGORIES = {flights:'Billets d’avion',lodging:'Logement',taxes:'Taxes',contractors:'Prestataires',salaries:'Salaires',other:'Autres frais'};
const STORAGE_KEY = 'marge-cost-models-v1';
const numericFields = ['sellingDayRate','purchaseDayRate','offDays','extraDays','overtimeHours','overtimeSellingRate','overtimePurchaseRate'];
const field = (row,key) => row.querySelector(`[data-cfield="${key}"]`);
const modelField = (row,key) => row.querySelector(`[data-mfield="${key}"]`);
function option(select,value,text){const o=document.createElement('option');o.value=value;o.textContent=text;select.append(o);}
function downloadJSON(value,filename){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}

export function initPlanner({getProject,beforeChange,onChange,onRemove,toast,switchTab}) {
  let models=[];
  try {const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');if(Array.isArray(saved))models=saved.filter(validCostModel);} catch {}
  let defaultModel=null,editing=null,editingScope=null;
  function storeModels(next){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(next));models=next;refreshModelOptions();return true;}catch{toast('Stockage indisponible. Exportez le modèle JSON pour le conserver.');return false;}}
  function modelSelect(select,current){select.replaceChildren();option(select,'','Aucun modèle de coûts locaux');if(current)option(select,'@current',`Copie actuelle — ${current.name}`);for(const m of models)option(select,m.id,m.name);select.value=current?'@current':'';}

  function refreshModelOptions(){ $('modelCount').textContent=models.length;modelSelect($('defaultCostModel'),defaultModel);$('consultantList').querySelectorAll('.consultant-card').forEach(card=>modelSelect(field(card,'costModel'),card._costModel));}
  function consultantCard(c,index){const card=document.createElement('article');card.className='editor-card consultant-card';card.dataset.id=c.id;card.dataset.type='consultant';card._costModel=c.costModel?structuredClone(c.costModel):null;card.innerHTML=`
    <div class="line-heading"><span class="line-index"></span><label class="line-name"><span class="sr-only">Nom du consultant</span><input data-cfield="name" type="text" maxlength="100" placeholder="Nom du consultant ou du profil"></label><button type="button" class="remove-line">×</button></div>
    <div class="consultant-dates"><label>Début de mission<input data-cfield="startDate" type="date" min="1900-01-01" max="2200-12-31" required></label><label>Fin de mission incluse<input data-cfield="endDate" type="date" min="1900-01-01" max="2200-12-31" required></label></div>
    <div class="consultant-rates"><label>Tarif de vente / jour<div class="input-wrap"><input data-cfield="sellingDayRate" type="number" min="0" max="100000000" step="0.01" required><span>€</span></div></label><label>Rémunération / achat par jour<div class="input-wrap"><input data-cfield="purchaseDayRate" type="number" min="0" max="100000000" step="0.01" required><span>€</span></div></label></div>
    <p class="consultant-pay-hint">Saisissez le coût de rémunération ou d’achat non compris dans le modèle local, sans le répéter dans les autres dépenses.</p>
    <div class="consultant-model-row"><label>Modèle de coûts locaux<select data-cfield="costModel"></select></label><button type="button" class="text-button adjust-consultant-costs">Ajuster les coûts</button></div>
    <details class="consultant-adjustments"><summary>Absences, week-ends et heures supplémentaires</summary><div class="consultant-adjustment-grid"><label>Absences et jours fériés dans le projet<input data-cfield="offDays" type="number" min="0" max="1000000" step="0.5" required></label><label>Jours de week-end travaillés dans le projet<input data-cfield="extraDays" type="number" min="0" max="1000000" step="0.5" required></label><label>Heures supplémentaires dans le projet<input data-cfield="overtimeHours" type="number" min="0" max="100000000" step="0.01" required></label><label>Vente par heure supplémentaire (€)<input data-cfield="overtimeSellingRate" type="number" min="0" max="100000000" step="0.01" required></label><label>Achat par heure supplémentaire (€)<input data-cfield="overtimePurchaseRate" type="number" min="0" max="100000000" step="0.01" required></label></div><p>Les heures sont ajoutées aux journées : saisissez chaque travail une seule fois. Les jours supplémentaires sont facturés au tarif journalier.</p></details>
    <div class="consultant-summary"><span class="consultant-days"></span><span class="consultant-local-total"></span><strong class="consultant-revenue"></strong></div>`;
    card.querySelector('.line-index').textContent=String(index+1).padStart(2,'0');
    for(const key of ['name','startDate','endDate',...numericFields])field(card,key).value=c[key];
    modelSelect(field(card,'costModel'),card._costModel);
    card.querySelector('.remove-line').setAttribute('aria-label',`Supprimer ${c.name}`);
    card.querySelector('.remove-line').addEventListener('click',()=>onRemove(c.id));
    card.querySelector('.adjust-consultant-costs').addEventListener('click',()=>{if(!beforeChange())return;openModel(card._costModel?structuredClone(card._costModel):newCostModel(uid()),{type:'consultant',id:c.id});});
    return card;
  }
  function populate(p){defaultModel=p.defaultCostModel?structuredClone(p.defaultCostModel):null;$('consultantList').replaceChildren(...p.consultants.map(consultantCard));if(!p.consultants.length){const empty=document.createElement('p');empty.className='empty-lines';empty.textContent='Ajoutez un consultant pour saisir ses dates et son tarif personnel.';$('consultantList').append(empty);}refreshModelOptions();}
  function readFields(){return {defaultCostModel:defaultModel?structuredClone(defaultModel):null,consultants:[...$('consultantList').querySelectorAll('.consultant-card')].map(card=>{const c={id:card.dataset.id,costModel:card._costModel?structuredClone(card._costModel):null};for(const key of ['name','startDate','endDate',...numericFields])c[key]=numericFields.includes(key)?Number(field(card,key).value):field(card,key).value;c.name=c.name.trim()||'Consultant sans nom';return c;})};}
  function onFormInput(event){if(event.target.id==='defaultCostModel'){const m=models.find(m=>m.id===event.target.value);if(m)defaultModel=structuredClone(m);else if(!event.target.value)defaultModel=null;modelSelect(event.target,defaultModel);}if(event.target.dataset.cfield==='costModel'){const card=event.target.closest('.consultant-card');const m=models.find(m=>m.id===event.target.value);if(m)card._costModel=structuredClone(m);else if(!event.target.value)card._costModel=null;modelSelect(event.target,card._costModel);}}
  function render(r){const p=getProject(),period=projectPeriod(p);$('projectPeriodLabel').textContent=`Du ${dateLabel(period.startDate)} au ${dateLabel(period.endDate)}`;$('consultantCount').textContent=p.consultants.length;$('consultantSubtotal').textContent=money(r.consultants.reduce((s,c)=>s+c.revenue,0));
    for(const card of $('consultantList').querySelectorAll('.consultant-card')){const c=r.consultants.find(c=>c.id===card.dataset.id);if(!c)continue;card.querySelector('.consultant-days').textContent=`${decimal(c.workedDays)} jours · ${decimal(c.overtimeHours)} h sup.`;card.querySelector('.consultant-local-total').textContent=`Coûts locaux : ${money(c.local.total)}`;card.querySelector('.consultant-revenue').textContent=`CA ${money(c.revenue)}`;card.setAttribute('aria-label',c.name);card.querySelector('.remove-line').setAttribute('aria-label',`Supprimer ${c.name}`);}
    const warnings=[];const noPay=r.consultants.filter(c=>(c.workedDays>0||c.overtimeHours>0)&&c.pay===0).length;if(noPay)warnings.push(`${noPay} consultant(s) sans rémunération saisie : vérifiez qu’elle est incluse ailleurs dans le budget.`);if(p.consultants.length&&p.revenues.length)warnings.push(`Le résultat inclut aussi ${p.revenues.length} autre(s) ligne(s) de revenus. Vérifiez qu’elles ne doublonnent pas les consultants.`);const outside=r.consultants.filter(c=>!c.calendarDays).length;if(outside)warnings.push(`${outside} consultant(s) hors période du projet : aucun revenu ni coût de mission retenu.`);$('planningWarnings').textContent=warnings.join(' ');$('planningWarnings').hidden=!warnings.length;renderTimeline(r,period);
  }
  function renderTimeline(r,period){const box=$('planningTimeline');box.replaceChildren();box.hidden=!r.consultants.length;if(!r.consultants.length)return;const heading=document.createElement('div');heading.className='timeline-heading';heading.textContent='Arrivées et départs';box.append(heading);const range=document.createElement('div');range.className='timeline-range';const left=document.createElement('span'),right=document.createElement('span');left.textContent=dateLabel(period.startDate);right.textContent=dateLabel(period.endDate);range.append(left,right);box.append(range);const span=period.end-period.start+86400000;for(const c of r.consultants){const row=document.createElement('div');row.className='timeline-row';const name=document.createElement('span');name.textContent=c.name;const track=document.createElement('div');track.className='timeline-track';track.setAttribute('aria-label',`${c.name} : du ${dateLabel(c.startDate)} au ${dateLabel(c.endDate)}, ${decimal(c.workedDays)} jours travaillés dans le projet`);const bar=document.createElement('div');bar.title=track.getAttribute('aria-label');if(c.calendarDays){bar.style.marginLeft=`${(c.start-period.start)/span*100}%`;bar.style.width=`${Math.max((c.end-c.start+86400000)/span*100,.3)}%`;track.append(bar);}else track.textContent='Hors période';row.append(name,track);box.append(row);}}
  $('addConsultantBtn').addEventListener('click',()=>{if(!beforeChange())return;const p=getProject();if(p.consultants.length>=100){toast('Un projet peut contenir 100 consultants.');return;}const period=projectPeriod(p);p.consultants.push({id:uid(),name:'Nouveau consultant',startDate:period.startDate,endDate:period.endDate,sellingDayRate:defaultModel?.suggestedRate||0,purchaseDayRate:0,offDays:0,extraDays:0,overtimeHours:0,overtimeSellingRate:0,overtimePurchaseRate:0,costModel:defaultModel?structuredClone(defaultModel):null});populate(p);onChange();const name=field($('consultantList').lastElementChild,'name');name.focus();name.select();});
  function showLibrary(){const list=$('modelList');list.replaceChildren();if(!models.length){const p=document.createElement('p');p.className='empty-projects';p.textContent='Créez ou importez votre premier modèle de coûts locaux.';list.append(p);}for(const m of models){const row=document.createElement('div');row.className='saved-project';const info=document.createElement('div'),title=document.createElement('h3'),meta=document.createElement('p');title.textContent=m.name;const cost=calculateCostModel(m,1);meta.textContent=`${m.lines.filter(l=>l.enabled).length} postes actifs · ${money(cost.daily)} / jour + ${money(cost.oneOff)} ponctuels`;info.append(title,meta);const actions=document.createElement('div');actions.className='saved-actions';for(const [label,handler]of [['Modifier',()=>openModel(structuredClone(m),{type:'library'})],['Copier',()=>openModel({...structuredClone(m),id:uid(),name:(m.name+' — copie').slice(0,100)},{type:'library'})],['Exporter',()=>downloadJSON({type:'marge-cost-model',version:1,model:m},'marge-modele-couts.json')]]){const b=document.createElement('button');b.type='button';b.className='button secondary';b.textContent=label;b.addEventListener('click',handler);actions.append(b);}const remove=document.createElement('button');remove.type='button';remove.className='delete-project';remove.textContent='Supprimer';remove.addEventListener('click',()=>{if(storeModels(models.filter(x=>x.id!==m.id))){showLibrary();toast('Modèle supprimé de la bibliothèque. Les copies des projets sont conservées.');}});actions.append(remove);row.append(info,actions);list.append(row);}}
  function openLibrary(){showLibrary();$('modelsDialog').showModal();}
  $('modelsBtn').addEventListener('click',openLibrary);$('manageModelsBtn').addEventListener('click',openLibrary);
  $('newModelBtn').addEventListener('click',()=>openModel(newCostModel(uid()),{type:'library'}));
  function modelRow(line){const tr=document.createElement('tr');tr.dataset.id=line.id;tr.innerHTML=`<td><input data-mfield="enabled" type="checkbox" aria-label="Poste actif"></td><td><input data-mfield="name" type="text" maxlength="150" required aria-label="Nom du coût"><select data-mfield="category" aria-label="Catégorie"></select></td><td><input data-mfield="amount" type="number" min="0" max="100000000" step="any" required aria-label="Montant unitaire"></td><td><select data-mfield="currency" aria-label="Devise"><option>USD</option><option>EUR</option></select></td><td><select data-mfield="basis" aria-label="Base de calcul"><option value="day">Par jour</option><option value="once">Ponctuel</option><option value="amortized">Réparti</option></select></td><td><input data-mfield="quantity" type="number" min="0" max="10000000" step="any" required aria-label="Quantité"></td><td><input data-mfield="referenceDays" type="number" min="0.000001" max="1000000" step="any" required aria-label="Jours de référence"></td><td><input data-mfield="taxed" type="checkbox" aria-label="Appliquer la TVA"></td><td><input data-mfield="buffered" type="checkbox" aria-label="Appliquer la sécurité ajoutée"></td><td><button type="button" class="remove-line" aria-label="Supprimer ce coût">×</button></td>`;for(const [id,name]of Object.entries(CATEGORIES))option(modelField(tr,'category'),id,name);for(const k of ['enabled','name','category','amount','currency','basis','quantity','referenceDays','taxed','buffered']){const v=line[k];const input=modelField(tr,k);if(input){if(input.type==='checkbox')input.checked=v;else input.value=v;}}syncModelRow(tr);tr.querySelector('.remove-line').addEventListener('click',()=>{tr.remove();previewModel();});return tr;}
  function syncModelRow(row){const active=modelField(row,'enabled').checked;row.classList.toggle('inactive',!active);row.querySelectorAll('[data-mfield]').forEach(input=>{if(input.dataset.mfield!=='enabled')input.disabled=!active;});modelField(row,'referenceDays').disabled=!active||modelField(row,'basis').value!=='amortized';}
  function openModel(m,scope){$('modelsDialog').close();editing=m;editingScope=scope;$('modelTitle').textContent=scope.type==='consultant'?'Coûts de ce consultant':'Configurer un modèle';$('modelName').value=m.name;$('modelUsdPerEur').value=m.usdPerEur;$('modelVat').value=m.vatRate;$('modelSuggestedRate').value=m.suggestedRate;$('modelSafetyMode').value=m.safetyMode;$('modelSafetyRate').value=m.safetyRate;$('modelUseBudgetFx').checked=m.useBudgetFx;$('modelBudgetFx').value=m.budgetEurPerUsd;$('modelNotes').value=m.notes;$('modelLines').replaceChildren(...m.lines.map(modelRow));$('saveModelBtn').textContent=scope.type==='consultant'?'Appliquer au consultant':'Enregistrer le modèle';$('useModelBtn').hidden=scope.type==='consultant';previewModel();$('modelDialog').showModal();}
  function readModel(){const m={version:1,id:editing.id,name:$('modelName').value.trim(),notes:$('modelNotes').value,usdPerEur:Number($('modelUsdPerEur').value),useBudgetFx:$('modelUseBudgetFx').checked,budgetEurPerUsd:Number($('modelBudgetFx').value),vatRate:Number($('modelVat').value),safetyMode:$('modelSafetyMode').value,safetyRate:Number($('modelSafetyRate').value),suggestedRate:Number($('modelSuggestedRate').value),lines:[...$('modelLines').children].map(row=>{const line={id:row.dataset.id};row.querySelectorAll('[data-mfield]').forEach(input=>line[input.dataset.mfield]=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value);if(line.basis!=='amortized'||!line.enabled)line.referenceDays=Number.isFinite(line.referenceDays)&&line.referenceDays>0?line.referenceDays:1;return line;})};if(!m.useBudgetFx)m.budgetEurPerUsd=Number.isFinite(m.budgetEurPerUsd)&&m.budgetEurPerUsd>0?m.budgetEurPerUsd:1;if(m.safetyMode!=='add'&&!Number.isFinite(m.safetyRate))m.safetyRate=0;return m;}
  function previewModel(){ $('modelBudgetFx').disabled=!$('modelUseBudgetFx').checked;$('modelSafetyRate').disabled=$('modelSafetyMode').value==='none';const invalid=[...$('modelForm').querySelectorAll('input:not(:disabled),textarea')].find(i=>!i.validity.valid||(i.type==='number'&&i.value===''));const m=readModel();if(invalid||!validCostModel(m)){$('modelError').hidden=false;$('modelError').textContent='Vérifiez les montants, le nom, les taux et les jours de référence du modèle.';$('modelPreview').textContent='Aperçu en attente de valeurs valides.';return null;}$('modelError').hidden=true;const preview=calculateCostModel(m,1);$('modelPreview').replaceChildren();for(const[label,value]of [['Coûts locaux / jour (indicatif)',money(preview.daily)],['Frais ponctuels / consultant',money(preview.oneOff)],['Coût pour 200 jours',money(calculateCostModel(m,200).total)]]){const item=document.createElement('div'),caption=document.createElement('span'),amount=document.createElement('strong');caption.textContent=label;amount.textContent=value;item.append(caption,amount);$('modelPreview').append(item);}$('modelFxExplanation').textContent=`Référence : 1 € = ${decimal(m.usdPerEur)} USD. Coûts USD convertis à 1 USD = ${decimal(modelExchangeRate(m))} €. ${m.safetyMode==='included'?'Sécurité déjà intégrée : aucune majoration supplémentaire.':m.safetyMode==='add'?`Sécurité ajoutée : ${decimal(m.safetyRate)} % après TVA sur les lignes cochées.`:'Aucune sécurité ajoutée.'}`;return m;}
  $('modelForm').addEventListener('submit',e=>e.preventDefault());$('modelForm').addEventListener('input',e=>{const row=e.target.closest('tr');if(row)syncModelRow(row);previewModel();});
  $('addModelLineBtn').addEventListener('click',()=>{if($('modelLines').children.length>=100){toast('Un modèle peut contenir 100 coûts.');return;}$('modelLines').append(modelRow({id:uid(),name:'Nouveau coût',category:'other',amount:0,currency:'EUR',basis:'day',quantity:1,referenceDays:1,enabled:true,taxed:false,buffered:false}));previewModel();});
  function saveModel(use=false){const m=previewModel();if(!m){$('modelForm').querySelector('input:invalid')?.focus();return;}if(editingScope.type==='consultant'){if(!beforeChange())return;const card=[...$('consultantList').querySelectorAll('.consultant-card')].find(c=>c.dataset.id===editingScope.id);if(!card){toast('Ce consultant n’est plus présent.');return;}card._costModel=structuredClone(m);modelSelect(field(card,'costModel'),card._costModel);onChange(true);$('modelDialog').close();toast('Coûts locaux mis à jour pour ce consultant.');return;}if(use&&!beforeChange())return;const next=models.some(x=>x.id===m.id)?models.map(x=>x.id===m.id?structuredClone(m):x):[structuredClone(m),...models];if(!storeModels(next))return;if(use){defaultModel=structuredClone(m);refreshModelOptions();onChange(true);switchTab('consultants');}$('modelDialog').close();toast(use?'Modèle enregistré : il sera copié sur les nouveaux consultants.':'Modèle enregistré dans votre bibliothèque.');}
  $('saveModelBtn').addEventListener('click',()=>saveModel(false));$('useModelBtn').addEventListener('click',()=>saveModel(true));
  $('exportModelBtn').addEventListener('click',()=>{const m=previewModel();if(m)downloadJSON({type:'marge-cost-model',version:1,model:m},'marge-modele-couts.json');});
  function importModel(value){const m=value?.type==='marge-cost-model'?value.model:value;if(!validCostModel(m))throw new Error('Format du modèle invalide.');openModel({...structuredClone(m),id:uid()},{type:'library'});toast('Modèle chargé. Vérifiez-le puis enregistrez-le dans votre bibliothèque.');}
  $('importModelBtn').addEventListener('click',()=>$('modelFile').click());$('modelFile').addEventListener('change',async()=>{try{const file=$('modelFile').files?.[0];if(!file)return;if(file.size>200000)throw new Error('Le modèle dépasse 200 Ko.');importModel(JSON.parse(await file.text()));}catch(error){toast(`Import impossible : ${error.message}`);}finally{$('modelFile').value='';}});
  async function restoreModelLink(){
    const compressed=location.hash.startsWith('#modeleGzip=');
    if(!compressed&&!location.hash.startsWith('#modele='))return;
    try{
      const data=location.hash.slice(compressed?12:8);
      history.replaceState(null,'',location.pathname+location.search);
      if(data.length>100000)throw new Error('Lien trop long.');
      const padded=data.replaceAll('-','+').replaceAll('_','/');
      let bytes=Uint8Array.from(atob(padded),c=>c.charCodeAt(0));
      if(compressed){
        if(typeof DecompressionStream!=='function')throw new Error('Votre navigateur doit être mis à jour pour lire ce lien.');
        const reader=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip')).getReader();
        const chunks=[];let size=0;
        while(true){const part=await reader.read();if(part.done)break;size+=part.value.length;if(size>200000){await reader.cancel();throw new Error('Modèle trop volumineux.');}chunks.push(part.value);}
        bytes=new Uint8Array(size);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}
      }
      importModel(JSON.parse(new TextDecoder().decode(bytes)));
    }catch(error){history.replaceState(null,'',location.pathname+location.search);toast(`Modèle du lien invalide : ${error.message}`);}
  }

  return {populate,readFields,onFormInput,render,restoreModelLink,refreshModelOptions};
}
